define("mod_teachingpractice/mod_form",["jquery","core/ajax","core/notification"],function($,Ajax,Notification){function loadAssignments(assignSelect,courseId,preselectId){if(!courseId||courseId==="0"){assignSelect.innerHTML='<option value="">--- Select linked course first ---</option>';assignSelect.disabled=false;return}assignSelect.innerHTML='<option value="">Loading assignments...</option>';assignSelect.disabled=true;Ajax.call([{methodname:"mod_teachingpractice_get_assignments",args:{courseid:parseInt(courseId,10)},done:function(assignments){assignSelect.disabled=false;assignSelect.innerHTML="";if(!assignments||assignments.length===0){assignSelect.innerHTML='<option value="">No assignments found in this course</option>';return}var def=document.createElement("option");def.value="";def.text="--- Select assignment ---";assignSelect.appendChild(def);assignments.forEach(function(a){var opt=document.createElement("option");opt.value=a.id;opt.text=a.name;if(String(a.id)===String(preselectId)){opt.selected=true}assignSelect.appendChild(opt)})},fail:function(err){assignSelect.disabled=false;assignSelect.innerHTML='<option value="">Error loading assignments</option>';Notification.exception(err)}}])}return{init:function(){var courseSelect=document.getElementById("id_linked_course");var assignSelect=document.getElementById("id_linked_assign");if(!courseSelect||!assignSelect){return}var savedAssignId=assignSelect.value||"";$(courseSelect).on("change",function(){loadAssignments(assignSelect,this.value,"")});if(courseSelect.value&&courseSelect.value!=="0"){loadAssignments(assignSelect,courseSelect.value,savedAssignId)}}}});
